// Traffic data simulation for HoneyGo
// In production, replace with Google Maps API or similar

const input = $input.first().json.body;
const origin = input.origin || 'Downtown';
const destination = input.destination || 'Airport';
const city = input.city || 'Phoenix';

// Get current hour for time-based traffic simulation
const hour = new Date().getHours();

// Base distance (would come from maps API)
const baseDistance = input.distance_miles || 15;
const baseDuration = baseDistance * 2; // ~2 min per mile base

// Traffic multipliers by time of day
let trafficLevel = 'light';
let congestionMultiplier = 1.0;
let reasoning = 'Normal traffic conditions';

// Rush hour detection
if ((hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 18)) {
  trafficLevel = 'heavy';
  congestionMultiplier = 1.8;
  reasoning = 'Rush hour traffic';
} else if ((hour >= 11 && hour <= 13) || (hour >= 19 && hour <= 21)) {
  trafficLevel = 'moderate';
  congestionMultiplier = 1.3;
  reasoning = 'Moderate traffic';
} else if (hour >= 22 || hour <= 5) {
  trafficLevel = 'minimal';
  congestionMultiplier = 0.9;
  reasoning = 'Late night, minimal traffic';
}

// City-specific adjustments
const cityMultipliers = {
  'new york': 1.4,
  'chicago': 1.25,
  'los angeles': 1.5,
  'phoenix': 1.0,
  'houston': 1.1
};

const cityFactor = cityMultipliers[city.toLowerCase()] || 1.0;
congestionMultiplier *= cityFactor;

const currentDuration = Math.round(baseDuration * congestionMultiplier);
const congestionPercentage = Math.round((congestionMultiplier - 1) * 100);

// Pricing multiplier based on traffic
let pricingMultiplier = 1.0;
if (trafficLevel === 'heavy') {
  pricingMultiplier = 1.35;
} else if (trafficLevel === 'moderate') {
  pricingMultiplier = 1.15;
} else if (trafficLevel === 'minimal') {
  pricingMultiplier = 1.0;
}

return {
  city: city,
  origin: origin,
  destination: destination,
  distance_miles: baseDistance,
  base_duration_minutes: baseDuration,
  current_duration_minutes: currentDuration,
  traffic_level: trafficLevel,
  congestion_percentage: congestionPercentage,
  pricing_multiplier: pricingMultiplier,
  reasoning: reasoning,
  timestamp: new Date().toISOString()
};
